create table if not exists public.managed_pages (id uuid primary key default gen_random_uuid(), owner_user_id uuid, parent_page_id uuid references public.managed_pages(id) on delete set null, account_type text not null check (account_type in ('owner','specialist','institution','client','service','delivery_worker')), display_name text not null, username text unique, avatar_url text, language text not null default 'ar', country_code text, is_clone boolean not null default false, is_linked_to_parent boolean not null default true, expires_at timestamptz, status text not null default 'active' check (status in ('active','expired','revoked')), created_at timestamptz not null default now());
create table if not exists public.managed_page_permissions (id uuid primary key default gen_random_uuid(), page_id uuid not null references public.managed_pages(id) on delete cascade, permission_key text not null, allowed boolean not null default false, constraint managed_page_permissions_unique unique(page_id, permission_key));
create table if not exists public.page_gifts (id uuid primary key default gen_random_uuid(), page_id uuid not null references public.managed_pages(id) on delete cascade, recipient_label text, share_token text unique not null, password_hint text, expires_at timestamptz, keep_linked boolean not null default false, detached_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.video_sources (id uuid primary key default gen_random_uuid(), title text not null, description text, language text not null, specialty_slug text not null, source_provider text not null check (source_provider in ('upload','youtube','vk','ok','mailru','my_mail','rutube','other')), source_url text not null, embed_url text, license_type text, rights_verified boolean not null default false, attribution text, category text not null default 'education', created_by uuid, is_published boolean not null default false, created_at timestamptz not null default now());
create index if not exists video_sources_language_specialty_idx on public.video_sources(language,specialty_slug);
alter table public.managed_pages enable row level security; alter table public.managed_page_permissions enable row level security; alter table public.page_gifts enable row level security; alter table public.video_sources enable row level security;
create policy if not exists "published video sources are public" on public.video_sources for select using (is_published = true);